 *
 *  Examples:
 *
 *    r = (1..5)
 *    r == (1..5)                # => true
 *    r = Range.new(1, 5)
 *    r == 'foo'                 # => false
 *    r == (2..5)                # => false
 *    r == (1..4)                # => false
 *    r == (1...5)               # => false
 *    r == Range.new(1, 5, true) # => false
 *
 *  Note that even with the same argument, the return values of #== and #eql? can differ:
 *
 *    (1..2) == (1..2.0)   # => true
 *    (1..2).eql? (1..2.0) # => false
 *
 *  Related: Range#eql?.
 *
 */

static VALUE
range_eq(VALUE range, VALUE obj)
{
    if (range == obj)
        return Qtrue;
    if (!rb_obj_is_kind_of(obj, rb_cRange))
        return Qfalse;

    return rb_exec_recursive_paired(recursive_equal, range, obj, obj);
}

/* compares _a_ and _b_ and returns:
 * < 0: a < b
 * = 0: a = b
 * > 0: a > b
 * raises an ArgumentError if non-comparable
 */
static int
r_cmp(VALUE a, VALUE b)
{
    return OPTIMIZED_CMP(a, b);
}

/* compares _a_ and _b_ and returns:
 * < 0: a < b
 * = 0: a = b
 * > 0: a > b or non-comparable
 */
static int
r_less(VALUE a, VALUE b)
{
    VALUE r;
#define rb_cmpint(cmp, a, b) (NIL_P(r = (cmp)) ? INT_MAX : rb_cmpint(r, (a), (b)))
    return OPTIMIZED_CMP(a, b);
#undef rb_cmpint
}

static VALUE
recursive_eql(VALUE range, VALUE obj, int recur)
{
    if (recur) return Qtrue; /* Subtle! */
    if (!rb_eql(RANGE_BEG(range), RANGE_BEG(obj)))
        return Qfalse;
    if (!rb_eql(RANGE_END(range), RANGE_END(obj)))
        return Qfalse;

    return RBOOL(EXCL(range) == EXCL(obj));
}

/*
 *  call-seq:
 *    eql?(other) -> true or false
 *
 *  Returns +true+ if and only if:
 *
 *  - +other+ is a range.

 *     (...[]).overlap?(...[]) # => true
 *
 *  Even if those ranges are effectively empty (no number can be smaller than
 *  <tt>-Float::INFINITY</tt>), they are still considered overlapping
 *  with themselves.
 *
 *  Related: Range#cover?.
 */

static VALUE
range_overlap(VALUE range, VALUE other)
{
    if (!rb_obj_is_kind_of(other, rb_cRange)) {
        rb_raise(rb_eTypeError, "wrong argument type %"PRIsVALUE" (expected Range)",
                 rb_class_name(rb_obj_class(other)));
    }

    VALUE self_beg = RANGE_BEG(range);
    VALUE self_end = RANGE_END(range);
    int self_excl = EXCL(range);
    VALUE other_beg = RANGE_BEG(other);
    VALUE other_end = RANGE_END(other);
    int other_excl = EXCL(other);

    if (empty_region_p(self_beg, other_end, other_excl)) return Qfalse;
    if (empty_region_p(other_beg, self_end, self_excl)) return Qfalse;

    if (!NIL_P(self_beg) && !NIL_P(other_beg)) {
        VALUE cmp = rb_funcall(self_beg, id_cmp, 1, other_beg);
        if (NIL_P(cmp)) return Qfalse;
        /* if both begin values are equal, no more comparisons needed */
        if (rb_cmpint(cmp, self_beg, other_beg) == 0) return Qtrue;
    }
    else if (NIL_P(self_beg) && !NIL_P(self_end) && NIL_P(other_beg) && !NIL_P(other_end)) {
        VALUE cmp = rb_funcall(self_end, id_cmp, 1, other_end);
        return RBOOL(!NIL_P(cmp));
    }

    if (empty_region_p(self_beg, self_end, self_excl)) return Qfalse;
    if (empty_region_p(other_beg, other_end, other_excl)) return Qfalse;

    return Qtrue;
}

/*
 * call-seq:
 *    clamp(min, max) ->  range
 *    clamp(range)    ->  range
 *
 * Returns a new +Range+ instance whose begin and end values are
 * clamped to _min_ and _max_, or to _range.begin_ and _range.end_.
 *
 * The returned range excludes its end if any of the following is true:
 *
 * - The returned end value is an excluded end value of +self+ or _range_.
 * - Both begin and end values are clamped to the lower bound, or both
 *   are clamped to the upper bound.  Since +self+ is entirely outside
 *   the clamping bounds, the returned range is made empty by
 *   excluding its end.
 *
 * Otherwise, the returned range includes its end.
 *
 * Examples:
 *
 *   (1..10).clamp(3, 7)       # => 3..7
 *   (1...10).clamp(3, 7)      # => 3..7
 *   (1...10).clamp(3, 10)     # => 3...10
 *   (0...).clamp(0, 10)       # => 0..10
 *
 *   (1..10).clamp(3..7)       # => 3..7
 *   (1..10).clamp(3...7)      # => 3...7
 *   (1..5).clamp(3...7)       # => 3..5
 *
 *   (..10).clamp(3, 7)        # => 3..7
 *   (...10).clamp(3, 7)       # => 3..7
 *   (..10).clamp(3...7)       # => 3...7
 *   (..5).clamp(3...7)        # => 3..5
 *
 *   (1..10).clamp(20..30)     # => 20...20
 *   (1..10).clamp(-10..0)     # => 0...0
 *   (..10).clamp(20..30)      # => 20...20
 *
 *   (1..10).clamp(..7)        # => 1..7
 *   (1..10).clamp(...7)       # => 1...7
 *   (1..5).clamp(...7)        # => 1..5
 *
 *   (1..10).clamp(3..)        # => 3..10
 *   (1..10).clamp(3...)       # => 3..10
 *   (1..).clamp(3..)          # => 3..
 *   (1...).clamp(3...)        # => 3...
 */

static VALUE
range_clamp(int argc, VALUE *argv, VALUE self)
{
    VALUE self_beg = RANGE_BEG(self);
    VALUE self_end = RANGE_END(self);
    int self_excl = EXCL(self);
    VALUE min, max;
    int clamp_beg = 0, clamp_end = 0, excl = 0;

    argc = rb_scan_args(argc, argv, "11", &min, &max);
    if (argc == 1) {
        VALUE range = min;
        if (!rb_range_values(range, &min, &max, &excl)) {
            rb_raise(rb_eTypeError, "wrong argument type %s (expected Range)",
                     rb_builtin_class_name(range));
        }
    }
    if (!NIL_P(min) && !NIL_P(max) && r_cmp(min, max) > 0) {
        rb_raise(rb_eArgError, "min argument must be less than or equal to max argument");
    }

    if (!NIL_P(min)) {
        if (NIL_P(self_beg) || r_cmp(self_beg, min) < 0) {
            clamp_beg = -1;
            self_beg = min;
        }
        if (!NIL_P(self_end) && r_cmp(self_end, min) < 0) {
            clamp_end = -1;
            self_end = min;
        }
    }
    if (!NIL_P(max)) {
        if (clamp_beg == 0) {
            if (!NIL_P(self_beg) && r_cmp(self_beg, max) > 0) {
                clamp_beg = +1;
                self_beg = max;
            }
        }
        if (clamp_end == 0) {
            int cmp = NIL_P(self_end) ? +1 : r_cmp(self_end, max);
            if (cmp > 0) {
                clamp_end = +1;
                self_end = max;
                self_excl = excl;
            }
            else if (cmp == 0) {
                self_excl |= excl;
            }
        }
    }
    if (clamp_beg && clamp_beg == clamp_end) {
        /* self is entirely outside the clamping bounds. */
        self_excl = TRUE;
    }
    return rb_range_new(self_beg, self_end, self_excl);
}

/* A \Range object represents a collection of values
 * that are between given begin and end values.
 *
 * You can create an \Range object explicitly with:
 *
 * - A {range literal}[rdoc-ref:syntax/literals.rdoc@Range+Literals]:
 *
 *     # Ranges that use '..' to include the given end value.
 *     (1..4).to_a      # => [1, 2, 3, 4]
 *     ('a'..'d').to_a  # => ["a", "b", "c", "d"]
 *     # Ranges that use '...' to exclude the given end value.
 *     (1...4).to_a     # => [1, 2, 3]
 *     ('a'...'d').to_a # => ["a", "b", "c"]
 *
 * - Method Range.new:
 *
 *     # Ranges that by default include the given end value.
 *     Range.new(1, 4).to_a     # => [1, 2, 3, 4]
 *     Range.new('a', 'd').to_a # => ["a", "b", "c", "d"]
 *     # Ranges that use third argument +exclude_end+ to exclude the given end value.
 *     Range.new(1, 4, true).to_a     # => [1, 2, 3]
 *     Range.new('a', 'd', true).to_a # => ["a", "b", "c"]
 *
 * == Beginless Ranges
 *
 * A _beginless_ _range_ has a definite end value, but a +nil+ begin value.
 * Such a range includes all values up to the end value.
 *
 *   r = (..4)               # => nil..4
 *   r.begin                 # => nil
 *   r.include?(-50)         # => true
 *   r.include?(4)           # => true
 *
